// Build-time GitHub stats, generated by scripts/generate-github-stats.mjs.
import data from "@/data/github-stats.json";

export interface RepositoryStats {
  fullName: string;
  url: string;
  stars: number;
  forks: number;
  pushedAt: string | null;
  latestRelease: string | null;
}

export interface GitHubStats {
  username: string;
  profileUrl: string;
  avatarUrl: string;
  publicRepos: number;
  followers: number;
  totalStars: number;
  totalForks: number;
  totalPullRequests: number;
  totalIssues: number;
  joinedYear: number;
  topLanguages: string[];
  repositories?: Record<string, RepositoryStats>;
  updatedAt: string;
}

export const githubStats: GitHubStats = data;

export function getRepositoryStats(fullName: string | undefined): RepositoryStats | undefined {
  if (!fullName) return undefined;
  return githubStats.repositories?.[fullName.toLowerCase()];
}

const dateFormat = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" });

export function formatDate(iso: string | null | undefined): string | undefined {
  if (!iso) return undefined;
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? undefined : dateFormat.format(date);
}

export const formatNumber = new Intl.NumberFormat("en-US").format;
